import React, {useState} from 'react';

function Square(props) {
    return <h1>{props.value}</h1>;
}

function Information(props) {
    return (
        <button className='square' onClick={props.onClick}>
            {props.value}
        </button>
    );
}

function clickHandler(squares, i) {
    const nextSquares = squares.slice();
    nextSquares[i] = 'O';
    setSquares(nextSquares);
}

export default function Board() {
    function clickHandler(squares, i) {
        const nextSquares = squares.slice();
        nextSquares[i] = xturn ? 'X' : 'O';

        setSquares(nextSquares);
        setXturn(!xturn);
    }

    const [squares, setSquares] = useState(Array(9).fill(null));
    const [xturn, setXturn] = useState(true);

    return (
        <>
            <div className='board-row'>
                <Square
                    value={squares[0]}
                    onClick={() => {
                        clickHandler(squares, 0);
                    }}
                />
                <Square
                    value={squares[1]}
                    onClick={() => {
                        clickHandler(squares, 1);
                    }}
                />
                <Square
                    value={squares[2]}
                    onClick={() => {
                        clickHandler(squares, 2);
                    }}
                />
            </div>
            <div className='board-row'>
                <Square
                    value={squares[3]}
                    onClick={() => {
                        clickHandler(squares, 3);
                    }}
                />
                <Square
                    value={squares[4]}
                    onClick={() => {
                        clickHandler(squares, 4);
                    }}
                />
                <Square
                    value={squares[5]}
                    onClick={() => {
                        clickHandler(squares, 5);
                    }}
                />
            </div>
            <div className='board-row'>
                <Square
                    value={squares[6]}
                    onClick={() => {
                        clickHandler(squares, 6);
                    }}
                />
                <Square
                    value={squares[7]}
                    onClick={() => {
                        clickHandler(squares, 7);
                    }}
                />
                <Square
                    value={squares[8]}
                    onClick={() => {
                        clickHandler(squares, 8);
                    }}
                />
            </div>
        </>
    );
}
